    // get role name by sys_id
    function getRoleNameBySysId(sysId) {
       if (sysId == global_admin_role_sys_id)
         return "public";

      return new SNC.RoleManagementAPI().getRoleNameById(sysId);
    }

    // find a compound sec.attr for the specified two scripts; create if missing
    function getCompoundSecAttrSysIdByScripts(script1, script2, tableName) {
        if (isScriptEmpty(script1) && isScriptEmpty(script2))
            return null;

        // first, try to find the existing sec.attr
        var sysIdComp = getSecAttrSysIdByName(getCompoundSecAttrNameByStrings(script1, script2));
        if (sysIdComp == null)
            sysIdComp = createCompoundSecAttrFromScripts(script1, script2, tableName);

        return sysIdComp;
    }

    // find a compound sec.attr for the specified script and another compound sec.attr
    function getCompoundSecAttrSysIdByScriptAndAnotherCompoundSecAttr(script, compSecAttrSysId, tableName) {
         if (compSecAttrSysId == null || compSecAttrSysId == '')
            return getCompoundSecAttrSysIdByScripts(script, null, tableName);

        if (isScriptEmpty(script))
            return compSecAttrSysId;

        // retrive the condtion of the existing sec.attr
        var gr = new GlideRecord('sys_security_attribute');
        if (!gr.get(compSecAttrSysId)) {
            if (ENABLE_LOG)
                gs.log('Compound SecAttr not found: ' + compSecAttrSysId);
            return null;
        }

        // check the condition:
        var condition = gr.condition;
        if (condition == null || condition == '') {
            if (ENABLE_LOG)
                gs.log('SecAttr has no condition: ' + compSecAttrSysId);
            return null;
        }

        // see if there's already existing compound sec.attr for the script and condition:
        var sysIdComp = getSecAttrSysIdByName(getCompoundSecAttrNameByStrings(script, condition));
        if (sysIdComp == null)
            sysIdComp = createCompoundSecAttrFromScriptAndCondition(script, condition, tableName);

        return sysIdComp;
    }

    // create compound sec.attr from scripst, including boolean sec.attr if missing
    function createCompoundSecAttrFromScripts(script1, script2, tableName) {
        var condition = "";
        var sep = "";
        var isCompoundSADependencyCustomized = false;

        // check if we already have the 1st boolean sec.attr; create if missing

        if (!isScriptEmpty(script1)) {
            var boolSecAttr1Name = getBooleanSecAttrNameByScript(script1);
            var sysIdBool = getSecAttrSysIdByName(boolSecAttr1Name);
            if (sysIdBool == null)
                createBooleanSecAttrFromScript(script1, tableName);

            condition = boolSecAttr1Name + "=true";
            sep = "^";
            isCompoundSADependencyCustomized = isSecurityAttributeCustomized(sysIdBool);
        }

        // check if we already have the 2nd boolean sec.attr; create if missing
        if (!isScriptEmpty(script2)) {
            var boolSecAttr2Name = getBooleanSecAttrNameByScript(script2);
            var sysIdBool = getSecAttrSysIdByName(boolSecAttr2Name);
            if (sysIdBool == null)
                createBooleanSecAttrFromScript(script2, tableName);

            isCompoundSADependencyCustomized = isCompoundSADependencyCustomized || isSecurityAttributeCustomized(sysIdBool);
            condition += sep + boolSecAttr2Name + "=true";
        }

        var name = getCompoundSecAttrNameByStrings(script1, script2);
        return isCompoundSADependencyCustomized ? generateSysIdForString(name) : createCompoundSecAttrFromCondition(name, condition, tableName);
    }


    // create compound sec.attr from script and condition, including boolean sec.attr if missing
    function createCompoundSecAttrFromScriptAndCondition(script, anotherCondition, tableName) {
        var condition = "";
        var sep = "";

        var global_or= '^NQ';
        var sep = "^";

        var isCompoundSADependencyCustomized = false;

        // check if we already have the 1st boolean sec.attr; create if missing
        if (!isScriptEmpty(script)) {
            var boolSecAttr1Name = getBooleanSecAttrNameByScript(script);
            var sysIdBool = getSecAttrSysIdByName(boolSecAttr1Name);
            if (sysIdBool == null)
                createBooleanSecAttrFromScript(script, tableName);

            isCompoundSADependencyCustomized = isSecurityAttributeCustomized(sysIdBool);
            condition = boolSecAttr1Name + "=true";
            sep = "^";
        }

        // check if we already have the 2nd boolean sec.attr; create if missing
        if (anotherCondition != null && anotherCondition != '') {
            if (anotherCondition.contains(global_or)){
                // in case there is global or operation, need to ANDed with each part
                var parts = anotherCondition.split(global_or);
                var transformedParts = parts.map(part => condition + sep + part);
                condition = transformedParts.join(global_or);
            }
            else
                condition += sep + anotherCondition;
        }

        var name = getCompoundSecAttrNameByStrings(script, anotherCondition);
        return isCompoundSADependencyCustomized ? generateSysIdForString(name) : createCompoundSecAttrFromCondition(name, condition, tableName);
    }


    function createBooleanSecAttrFromScript(script, tableName) {
        var TEMPLATE_BOOLEAN_SECURITY_ATTRIBUTE =
	"";

        var template = GlideStringUtil.base64Decode(TEMPLATE_BOOLEAN_SECURITY_ATTRIBUTE);
        var name = getBooleanSecAttrNameByScript(script);
        var sysId = generateSysIdForString(name);
        var description = "Boolean Security Attribute: Auto-generated by write-audit from scripts based on read ACLs for table: " + tableName;
        var condition = '';
	// apply work-arounds to the script:
	script = applyScriptWorkAround(script);

        if(isSecurityAttributeCustomized(sysId)) {
            if (ENABLE_LOG)
                gs.log("Skipping Boolean Security Attribute creation for sys_id: " + sys_id + " as it has been customized");
        } else {
            var xml = replaceSecAttrTokensAndEncode(template, sysId, name, description, script, condition);
            loadXML(xml, BOOLEAN_SA_TYPE);
        }

        return sysId;
    }

    function createCompoundSecAttrFromCondition(name, condition, tableName) {
        var TEMPLATE_COMPOUND_SECURITY_ATTRIBUTE =
	"";

        var template = GlideStringUtil.base64Decode(TEMPLATE_COMPOUND_SECURITY_ATTRIBUTE);
        var sysId = generateSysIdForString(name);
        var description = "Compound Security Attribute: Auto-generated by write-audit to evaluate boolean Security Attributes based on read ACLs for table: " + tableName;
        var script = '';

        if(isSecurityAttributeCustomized(sysId)) {
            if (ENABLE_LOG)
                gs.log("Skipping Compound Security Attribute creation for sys_id: " + sys_id + " as it has been customized");
        } else {
            var xml = replaceSecAttrTokensAndEncode(template, sysId, name, description, script, condition);
            loadXML(xml, COMPOUND_SA_TYPE);
        }
        return sysId;
    }


    function replaceSecAttrTokensAndEncode(template, sysId, name, description, script, condition) {
        var TOKEN_SYS_ID = "%%SYS_ID%%";
        var TOKEN_NAME = "%%NAME%%";
        var TOKEN_DESCRIPTION = "%%DESCRIPTION%%";
        var TOKEN_SCRIPT = "%%SCRIPT%%";
        var TOKEN_CONDITION = "%%CONDITION%%";

        // Note: the order my matter if script contains other tokens
        var result = template
            .replaceAll(TOKEN_SYS_ID, sysId)
            .replaceAll(TOKEN_NAME, name)
            .replaceAll(TOKEN_DESCRIPTION, description)
            .replaceAll(TOKEN_SCRIPT, script)
            .replaceAll(TOKEN_CONDITION, condition);

        return result;
    }


    // load XML into DB
    function loadXML(xml, type) {
        var um = new GlideUpdateManager2();
        if ( !DRY_RUN)
            um.loadXML(xml);

        if (type == BOOLEAN_SA_TYPE)
            results.details.generated_acls.summary.security_attribute.boolean_sa_count++;
        else if (type == COMPOUND_SA_TYPE)
            results.details.generated_acls.summary.security_attribute.compound_sa_count++;
    }

    // find sys_id of sec.attr, null if not found
    function getSecAttrSysIdByName(name) {
        var sysId = null;
        var gr = new GlideRecord('sys_security_attribute');
        if (gr.get('name', name))
            sysId = gr.sys_id;

        return sysId;
    }

    // get boolean sec.attr name by its script
    function getBooleanSecAttrNameByScript(script) {
        var PREFIX = "SAB_";
        return PREFIX + getHashForString(script);
    }


    // build script for conditional_table_query_range, e.g. "answer=new global.SNCAPICallWrapper().hasRightsToConditionalTableQueryRange('incident');"
    function getScriptForConditionalTableQueryRange(tableName) {
	var TEMPLATE = "answer=new global.SNCAPICallWrapper().hasRightsToConditionalTableQueryRange('%%TABLE_NAME%%');";
        var TOKEN_TABLE_NAME = "%%TABLE_NAME%%";
        var result = TEMPLATE.replaceAll(TOKEN_TABLE_NAME, tableName);

        return result;
    }


    // get compound sec.attr name by either script1+script2 or by script+condition
    function getCompoundSecAttrNameByStrings(str1, str2) {
        if (str1 == null)
            str1 = '';

        if (str2 == null)
            str2 = '';

        var PREFIX = "SAC_";
        return PREFIX + getHashForString(''+ str1 + str2);
    }

    // mark a record as created/updated by marker
    function markRecord(tableName, sysId) {
        var marker = getMarker();
        var dbu = new GlideDBUpdate(tableName);
        var subq = new GlideDBQuery(tableName);
        subq.addQuery('sys_id', sysId);
        dbu.setQuery(subq);
        dbu.setValue('sys_created_by', marker);
        dbu.setValue('sys_updated_by', marker);
        dbu.execute();
        dbu.close();
    }

    // marker to identify the ACLs, ACL-Roles, SecAttrs that we are creating
    function getMarker() {
        return "@@snc_write_audit@@";
    }

    function getExternalAclMarker() {
        return "@@snc_write_audit_external_acl@@";
    }

    // generate sys_id for the given string
    function generateSysIdForString(str) {
        var BASE = 'bc91c2a5f334621048dff3de56968ca8';
        var hash = '' + getHashForString(str);
        var len = hash.length;
        var result = BASE.substr(0, 32-len) + hash;
        return result;
    }

    // generate hash code from a String
    function getHashForString(str) {
        var hash = 0;
        var s = ''+ (str == null ? '' : str);
        for (var i = 0; i < s.length; i++)
            hash = Math.imul(31, hash) + s.charCodeAt(i) | 0;

        return hash & 0x7fffffff;
    }

    // activate all Security Atteributes and ACLs that were generated by write-audit
    function activateGeneratedObjects() {
        changeActiveGeneratedObjects(true);
    }

    function changeActiveGeneratedObjects(activeFlag) {
        changeActiveGeneratedObjectsForTable(activeFlag, "sys_security_attribute");
        changeActiveGeneratedObjectsForTable(activeFlag, "sys_security_acl");
    }

    function changeActiveGeneratedObjectsForTable(activeFlag, tableName) {
        var mu = new GlideMultipleUpdate(tableName);
        mu.addQuery("sys_created_by", getMarker());
        mu.addQuery("sys_updated_by", getMarker());
        mu.setValue('active', activeFlag );
        mu.execute();
        mu.close();
    }

